ST.xhtml:
parts.configManager( isEnabled := operator_ref = OperatorStatus.tech );
stat.busy := F_BusyStatus(
    superState := TRUE,
    isBusy := (stat.init = InitializationStatus.initializing) OR forced);
proc.initialize( isEnabled := (NOT(stat.init = InitializationStatus.initialized)) AND ((NOT(stat.init = InitializationStatus.initializing)) AND (NOT(stat.init = InitializationStatus.locked))) );
proc.powerOnPc( isEnabled := (stat.init = InitializationStatus.initialized) AND (NOT(powerPC)) );
proc.powerOffPc( isEnabled := powerPC );
proc.powerOnMount( isEnabled := (stat.init = InitializationStatus.initialized) AND ((NOT(powerMount)) AND ((NOT(stat.health = HealthStatus.bad)) AND (NOT(forced)))) );
proc.powerOffMount( isEnabled := powerMount AND (NOT(forced)) );
proc.manualPowerOn( isEnabled := (operator_ref = OperatorStatus.tech) AND (NOT(forced)) );
proc.manualPowerOff( isEnabled := forced AND (operator_ref = OperatorStatus.tech) );
proc.lock( isEnabled := (operator_ref = OperatorStatus.tech) AND (NOT(stat.init = InitializationStatus.locked)) );
proc.unlock( isEnabled := (operator_ref = OperatorStatus.tech) AND (stat.init = InitializationStatus.locked) );
proc.reset( isEnabled := TRUE );

THIS^.editableConfig := model.editableConfig;
THIS^.parts.configManager._copyFromModel_ConfigManager( model := model.parts.configManager );
THIS^.proc.initialize._copyFromModel_Process( model := model.proc.initialize );
THIS^.proc.powerOnPc._copyFromModel_Process( model := model.proc.powerOnPc );
THIS^.proc.powerOffPc._copyFromModel_Process( model := model.proc.powerOffPc );
THIS^.proc.powerOnMount._copyFromModel_Process( model := model.proc.powerOnMount );
THIS^.proc.powerOffMount._copyFromModel_Process( model := model.proc.powerOffMount );
THIS^.proc.manualPowerOn._copyFromModel_Process( model := model.proc.manualPowerOn );
THIS^.proc.manualPowerOff._copyFromModel_Process( model := model.proc.manualPowerOff );
THIS^.proc.lock._copyFromModel_Process( model := model.proc.lock );
THIS^.proc.unlock._copyFromModel_Process( model := model.proc.unlock );
THIS^.proc.reset._copyFromModel_Process( model := model.proc.reset );

model.temp := THIS^.temp;
model.lsAz1 := THIS^.lsAz1;
model.lsAz2 := THIS^.lsAz2;
model.lsAz3 := THIS^.lsAz3;
model.hsAz := THIS^.hsAz;
model.lsAl1 := THIS^.lsAl1;
model.lsAl2 := THIS^.lsAl2;
model.hsAl := THIS^.hsAl;
model.editableConfig := THIS^.editableConfig;
model.actualStatus := THIS^.actualStatus;
model.fan := THIS^.fan;
model.config := THIS^.config;
model.powerPC := THIS^.powerPC;
model.powerMount := THIS^.powerMount;
model.forced := THIS^.forced;
model.stat := THIS^.stat;
THIS^.parts.configManager._copyToModel_ConfigManager( model := model.parts.configManager );
THIS^.proc.initialize._copyToModel_Process( model := model.proc.initialize );
THIS^.proc.powerOnPc._copyToModel_Process( model := model.proc.powerOnPc );
THIS^.proc.powerOffPc._copyToModel_Process( model := model.proc.powerOffPc );
THIS^.proc.powerOnMount._copyToModel_Process( model := model.proc.powerOnMount );
THIS^.proc.powerOffMount._copyToModel_Process( model := model.proc.powerOffMount );
THIS^.proc.manualPowerOn._copyToModel_Process( model := model.proc.manualPowerOn );
THIS^.proc.manualPowerOff._copyToModel_Process( model := model.proc.manualPowerOff );
THIS^.proc.lock._copyToModel_Process( model := model.proc.lock );
THIS^.proc.unlock._copyToModel_Process( model := model.proc.unlock );
THIS^.proc.reset._copyToModel_Process( model := model.proc.reset );
